class Solution {
public:
    int duplicateNumbersXOR(vector<int>& nums) {
        unordered_map<int,int> c;
        for (int x : nums) c[x]++;
        int ans = 0;
        for (auto& p : c) if (p.second == 2) ans ^= p.first;
        return ans;
    }
};

