class Solution {
    public int duplicateNumbersXOR(int[] nums) {
        Map<Integer,Integer> c = new HashMap<>();
        for (int x : nums) c.merge(x, 1, Integer::sum);
        int ans = 0;
        for (var e : c.entrySet()) if (e.getValue() == 2) ans ^= e.getKey();
        return ans;
    }
}

